class QueryBuilder {
  #q = { select: '*', where: [] };
  select(...f) { this.#q.select = f.join(', ') || '*'; return this; }
  where(c)    { this.#q.where.push(c); return this; }
  build()     { return `SELECT ${this.#q.select} FROM t WHERE ${this.#q.where.join(' AND ')}`; }
}
const sql = new QueryBuilder().select('id').where('active = true').build();
